import {ingredients} from './ingredients.js';
// Single source of truth: { editing, removed: applied ids, draft: ids in the open editor, combo, size, cart }.
export const initial={removed:[],draft:[],editing:false,combo:true,size:'M',cart:[]};
export function reducer(s,a){switch(a.type){case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||ingredients.find(i=>i.id===a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value};case'size':return {...s,size:a.value};case'add':return {...s,cart:[...s.cart,{removed:[...s.removed],combo:s.combo,size:s.size,price:price(s)}]};case'delete':return {...s,cart:s.cart.filter((_,i)=>i!==a.index)};default:return s}}
export const fees={P:900,M:1200,G:1500},money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>3190+(s.combo?fees[s.size]:0);
